<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,allPages,download} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import PrivateImage from '../components/PrivateImage.vue';import EmptyState from '../components/EmptyState.vue';import {FlaskConical,Timer} from 'lucide-vue-next'
const rows=ref<any[]>([]),versions=ref<any[]>([]),models=ref<any[]>([]),form=ref({name:'',protocol:'',version:'',model:'',confidence:.25}),selected=ref<any>(null),samples=ref<any[]>([]),current=ref<any>(null),participant=ref(''),started=ref<number|null>(null),summary=ref<any>(null),show=ref(false);const {error,success,busy,act}=usePage()
async function load(){rows.value=await allPages('evaluations/')};onMounted(()=>act(async()=>{await load();versions.value=await allPages('versions/');models.value=await allPages('models/')}))
const create=()=>act(async()=>{await api.post('evaluations/',form.value);show.value=false;await load()},'Protocolo y muestras congelados. Registra las observaciones sin consultar las predicciones.')
const open=(row:any)=>act(async()=>{selected.value=row;samples.value=(await api.get(`evaluations/${row.id}/samples/`)).data;summary.value=null;current.value=null;started.value=null})
function imageLoaded(){started.value=performance.now()}
function begin(sample:any){current.value=sample;started.value=null}
const observe=(positive:boolean)=>act(async()=>{if(!started.value)throw new Error('Espera a que cargue la imagen.');const elapsed=performance.now()-started.value;await api.post(`evaluations/${selected.value.id}/observe/`,{sample:current.value.id,participant:participant.value,positive,elapsed_ms:elapsed});current.value=null;started.value=null;samples.value=(await api.get(`evaluations/${selected.value.id}/samples/`)).data},'Observación registrada.')
const run=()=>act(async()=>{await api.post(`evaluations/${selected.value.id}/run/`);await load()},'Evaluación del modelo encolada. Consulta Trabajos.')
const results=()=>act(async()=>{summary.value=(await api.get(`evaluations/${selected.value.id}/summary/`)).data})
</script>
<template><div class="mb-7 flex flex-wrap justify-between gap-4"><div><h1 class="heading">De los resultados a la evidencia</h1><p class="subheading">Compara el sistema y la inspección manual sobre las mismas muestras de prueba.</p></div><button class="btn self-start" @click="show=!show">Nueva evaluación</button></div><Notice :error="error" :success="success"/>
<form v-if="show" class="card mb-6 space-y-4" @submit.prevent="create"><label class="label">Nombre</label><input v-model="form.name" class="input" required/><div class="grid gap-4 md:grid-cols-2"><div><label class="label">Versión con test independiente</label><select v-model="form.version" class="input" required><option value="">Seleccionar</option><option v-for="v in versions" :key="v.id" :value="v.id">{{v.dataset_name}} · v{{v.number}}</option></select></div><div><label class="label">Modelo</label><select v-model="form.model" class="input" required><option value="">Seleccionar</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></select></div></div><label class="label">Protocolo de comparación</label><textarea v-model="form.protocol" rows="4" class="input" required placeholder="Define participantes, referencia especializada, unidad fruto/multivista, orden aleatorio, hardware, criterio de clasificación, tamaño muestral y tiempos comparables. El cronómetro manual mide desde que se muestra la imagen hasta responder; no incluye captura."/><label class="label">Umbral fijo de confianza</label><input v-model.number="form.confidence" type="number" min=".01" max=".99" step=".01" class="input max-w-xs"/><button class="btn" :disabled="busy">Guardar y fijar protocolo</button></form>
<div class="grid gap-4 md:grid-cols-3"><button v-for="row in rows" :key="row.id" @click="open(row)" class="card text-left" :class="selected?.id===row.id?'!border-emerald-500':''"><FlaskConical :size="20" class="mb-3 text-emerald-700"/><h2 class="font-semibold">{{row.name}}</h2><p class="mt-2 text-xs text-slate-400">{{row.sample_count}} imágenes de prueba · protocolo fijo</p></button></div><EmptyState v-if="!rows.length" title="Prepara tu evaluación experimental" text="Necesitas una versión congelada y un modelo entrenado. Los resultados aparecerán después de ejecutar las pruebas."/>
<section v-if="selected" class="card mt-6"><h2 class="text-xl font-semibold">{{selected.name}}</h2><p class="my-4 whitespace-pre-wrap text-sm leading-6 text-slate-500">{{selected.protocol}}</p><div class="grid gap-6 xl:grid-cols-2"><section class="rounded-xl border border-slate-200 p-5"><h3 class="mb-4 font-semibold">Inspección manual</h3><label class="label">Código del participante</label><input v-model="participant" class="input mb-4" placeholder="Ejemplo: P01 (seudónimo)" :disabled="!!current"/><p class="mb-4 text-xs text-slate-500">No consultes los resultados del sistema antes de completar tus observaciones. Las muestras se muestran en orden aleatorio fijo.</p><div v-if="!current" class="max-h-64 space-y-2 overflow-auto"><button v-for="(sample,index) in samples" :key="sample.id" class="flex w-full justify-between rounded-lg border border-slate-100 p-3 text-left text-xs hover:bg-slate-50" :disabled="!participant||sample.completed.includes(participant)" @click="begin(sample)"><span>Muestra {{index+1}} · {{sample.fruit_code}}</span><span>{{sample.completed.includes(participant)?'Registrada':'Inspeccionar →'}}</span></button></div><div v-else><PrivateImage :key="current.id" :src="`evaluations/${selected.id}/sample-file/?sample=${current.id}`" class="aspect-square w-full object-contain" @loaded="imageLoaded"/><p class="my-3 flex items-center gap-2 text-xs text-slate-500"><Timer :size="14"/>{{started?'Cronómetro activo':'Cargando imagen…'}}</p><div class="flex gap-2"><button class="btn" :disabled="busy||!started" @click="observe(true)">Roña visible</button><button class="btn-secondary" :disabled="busy||!started" @click="observe(false)">Sin roña visible</button></div></div></section><section class="rounded-xl bg-slate-50 p-5"><h3 class="font-semibold">Evaluación del sistema</h3><p class="my-4 text-xs leading-6 text-slate-500">Ejecuta YOLOv8 sobre test para calcular mAP y resultados por imagen. La comparación manual se agrega por fruto; los tiempos de sus vistas se suman.</p><div class="flex flex-wrap gap-2"><button class="btn" :disabled="busy" @click="run">Ejecutar evaluación</button><button class="btn-secondary" :disabled="busy" @click="results">Consultar resultados</button><button class="btn-secondary" @click="act(()=>download(`evaluations/${selected.id}/export/`,'evaluacion.xlsx'))">Exportar evidencia</button></div><div v-if="summary" class="mt-5"><p class="text-xs text-amber-800">Los valores p son exploratorios: no confirman automáticamente la hipótesis. Revisa el protocolo y los supuestos.</p><div v-for="(values,p) in summary.participants" :key="p" class="mt-4 rounded-xl bg-white p-4"><h4 class="font-semibold">{{p}} · {{values.system.n}} frutos pareados</h4><div class="mt-3 grid grid-cols-2 gap-3"><div><p class="label">F1 sistema</p>{{values.system.f1?.toFixed(3)??'No definido'}}</div><div><p class="label">F1 manual</p>{{values.manual.f1?.toFixed(3)??'No definido'}}</div><div><p class="label">Tiempo sistema</p>{{values.mean_system_ms.toFixed(1)}} ms</div><div><p class="label">Tiempo manual</p>{{values.mean_manual_ms.toFixed(1)}} ms</div></div></div><p v-if="!Object.keys(summary.participants).length" class="my-4 text-xs text-slate-500">Faltan resultados del sistema u observaciones manuales completas por fruto.</p><details class="mt-4 text-xs"><summary>Métricas y análisis detallados</summary><pre class="mt-3 max-h-96 overflow-auto rounded-xl bg-white p-3">{{JSON.stringify(summary,null,2)}}</pre></details></div></section></div></section></template>
